    var d = { id: id, cue: cue, el: this.element(t), fade: 0, target: 1, started: this.now(), leaving: false, gain: Math.pow(10, t.gainDb / 20), once: cue === 'end' };
    var start = at !== null && at !== undefined ? at : t.in;
